<?php
namespace CloudHost247\Ovh\Reconciliation;use CloudHost247\Ovh\Services\ConnectionResolver;use WHMCS\Database\Capsule;use RuntimeException;
final class OrderPoller
{private$r;function __construct(ConnectionResolver$r){$this->r=$r;}function pollPending($limit=50){$discovery=(new OrderDiscovery($this->r))->discoverMissing($limit);$rows=Capsule::table('mod_cloudhost247_ovh_services')->whereIn('status',array('pending','ordering','reconciliation_required'))->whereNotNull('remote_order_id')->limit((int)$limit)->get();$result=array('completed'=>0,'pending'=>0,'failed'=>0,'intervention'=>0,'discovery'=>$discovery);foreach($rows as$s){try{$c=$this->r->endpoint($s->endpoint_id);$status=$c->get('/me/order/'.rawurlencode($s->remote_order_id).'/status');$state=is_string($status)?$status:(string)($status['status']??'unknown');if(in_array(strtolower($state),array('cancelled','canceled','error','failed'),true)){Capsule::table('mod_cloudhost247_ovh_services')->where('id',$s->id)->update(array('status'=>'failed','updated_at'=>date('Y-m-d H:i:s')));$result['failed']++;continue;}if(!in_array(strtolower($state),array('delivered','completed','complete'),true)){$result['pending']++;continue;}$ids=(array)$c->get('/me/order/'.rawurlencode($s->remote_order_id).'/details');$detailRows=array();foreach($ids as$id)$detailRows[]=$c->get('/me/order/'.rawurlencode($s->remote_order_id).'/details/'.rawurlencode($id));$resolved=(new OrderResourceResolver())->resolve($detailRows);$serviceName=$resolved['status']==='resolved'?$resolved['service_name']:null;if(!$serviceName){Capsule::table('mod_cloudhost247_ovh_services')->where('id',$s->id)->update(array('status'=>'intervention_required','updated_at'=>date('Y-m-d H:i:s')));$result['intervention']++;continue;}if(Capsule::table('mod_cloudhost247_ovh_services')->where('endpoint_id',$s->endpoint_id)->where('remote_service_name',$serviceName)->where('id','!=',$s->id)->exists())throw new RuntimeException('Delivered OVH service is already bound elsewhere.');Capsule::table('mod_cloudhost247_ovh_services')->where('id',$s->id)->update(array('remote_service_name'=>$serviceName,'status'=>'active','last_synced_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')));Capsule::table('mod_cloudhost247_ovh_operations')->where('whmcs_service_id',$s->whmcs_service_id)->where('operation','provision')->update(array('status'=>'completed','remote_id'=>$serviceName,'updated_at'=>date('Y-m-d H:i:s')));$result['completed']++;}catch(\Throwable$e){$result['failed']++;}}return$result;}}
